import{_ as o,o as d,c as t,ae as c}from"./chunks/framework.YL6nI5ZP.js";const g=JSON.parse('{"title":"The 2D Mesh & WebGPU Subsystem","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/04-two-d-mesh-and-webgpu.md","filePath":"explanation/04-two-d-mesh-and-webgpu.md"}'),a={name:"explanation/04-two-d-mesh-and-webgpu.md"};function s(r,e,n,i,l,p){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="the-2d-mesh-webgpu-subsystem" tabindex="-1">The 2D Mesh &amp; WebGPU Subsystem <a class="header-anchor" href="#the-2d-mesh-webgpu-subsystem" aria-label="Permalink to &quot;The 2D Mesh &amp; WebGPU Subsystem&quot;">​</a></h1><p>The experimental surface-routing work: how the 2D mesh is generated, coupled to the 1D network, serialized into the INP, rendered, and finally re-implemented on the GPU as a WGSL marcher.</p><p>Two generations coexist:</p><ol><li><strong>Legacy mesh generator</strong> (<code>mesh2d.js</code>) — <code>poly2tri</code> per-subcatchment triangulation with an earclip fallback ladder.</li><li><strong>Production Triangle pipeline</strong> (<code>mesh2dPslg.js</code> + <code>mesh2dTriangle.js</code> + <code>mesh2dTerrain.js</code>) — constrained Delaunay over the whole domain via the vendored Shewchuk Triangle WASM.</li><li><strong>WebGPU marcher</strong> (<code>public/webgpu/</code>) — a WGSL re-implementation of the engine&#39;s explicit local-inertial solver, run in parallel to (and as an alternative to) the WASM 2D solver.</li></ol><h2 id="coordinate-foundation-—-mesh2dproj-js" tabindex="-1">Coordinate foundation — <code>mesh2dProj.js</code> <a class="header-anchor" href="#coordinate-foundation-—-mesh2dproj-js" aria-label="Permalink to &quot;Coordinate foundation — `mesh2dProj.js`&quot;">​</a></h2><p>All mesh geometry uses <strong>local metres relative to an origin centroid</strong> with an equirectangular approximation: <code>makeTransform(origin)</code> (<code>mesh2dProj.js:16</code>); <code>METERS_PER_DEGREE_LAT = 111320</code>; lng scaled by <code>cos(lat)</code>. <code>originFromModel(Net)</code> (<code>:43</code>) = centroid of node + subcatchment vertices. Not a true projection, but adequate for km-scale domains.</p><h2 id="the-mesh-data-model-—-net-setindexedmesh-network-js-874" tabindex="-1">The mesh data model — <code>Net.setIndexedMesh</code> (<code>network.js:874</code>) <a class="header-anchor" href="#the-mesh-data-model-—-net-setindexedmesh-network-js-874" aria-label="Permalink to &quot;The mesh data model — `Net.setIndexedMesh` (`network.js:874`)&quot;">​</a></h2><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mesh2DIndexed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  origin: { lng, lat },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  vertices: [{ x, y, z, lng, lat, tag, nodeId }],       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// local metres + geo + rim Z</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  triangles: [{ v:[i0,i1,i2], n, tag }],                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// n = Manning&#39;s, tag = subcatchment id</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  vertexNodeMap: [{ vertexIndex, nodeId, cd, area }],   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 1D↔2D coupling rows</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  nodeVertexIndex: { nodeId → vertexIndex },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  options: { solver + coupling options }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The legacy <code>Net.mesh2D[]</code> cell array (closed rings, stable <code>M2D_&lt;i+1&gt;</code> ids) is derived from it for the map layers. <code>inpParser.js:496-519</code> re-hydrates the same shape from <code>.inp</code>.</p><h2 id="pslg-construction-—-mesh2dpslg-js" tabindex="-1">PSLG construction — <code>mesh2dPslg.js</code> <a class="header-anchor" href="#pslg-construction-—-mesh2dpslg-js" aria-label="Permalink to &quot;PSLG construction — `mesh2dPslg.js`&quot;">​</a></h2><p><code>Mesh2DPslg.fromNetwork(sources, opts)</code> (<code>mesh2dPslg.js:128</code>) builds the Triangle PSLG in numbered phases:</p><ol><li><strong>Boundary</strong> (<code>:185</code>): a GeoJSON polygon is projected, Douglas-Peucker simplified (<code>dpSimplify</code>, <code>:53</code>) and densified (<code>densify</code>, <code>:84</code>); constraint segments with <code>marker=1</code>; default background region <code>attr=0</code>. Without a boundary, an <strong>auto domain</strong> = convex hull (<code>convexHull</code>, <code>:116</code>) buffered by <code>domainBuffer</code> (default 50 m).</li><li><strong>Subcatchments</strong> (<code>:271</code>): each becomes a Triangle <strong>region seed</strong> (mapped via <code>regionAttrToSub</code>) and optionally a constraint ring (<code>marker=2</code>) when <code>useSubRings</code>.</li><li><strong>Nodes</strong> (<code>:292</code>): hydraulic nodes become <strong>Steiner vertices</strong> tagged with their node id (enforcing <code>minNodeSep</code>); with <code>useRimZ</code>, vertex Z = <code>invertEl + maxDepth</code> (rim).</li><li><strong>Conduits</strong> (<code>:327</code>): conduit paths become constraint segments with unique <code>marker=100+k</code>, mapped back via <code>markerToConduit</code>.</li><li><strong>Constraint layers</strong> (<code>:349</code>): imported points/lines/polygons become constraint vertices/segments (<code>marker=3</code>); polygons ticked <strong>&quot;block flow (impermeable)&quot;</strong> become <strong>holes</strong> (with a &quot;swallows domain&quot; guard).</li><li><strong>Segment dedupe</strong> (<code>:409</code>) by <code>min:max</code> point key; <strong>crossing-segment removal</strong> (<code>:422</code>) via a bbox-grid (25 m buckets) <code>segsCross</code> test.</li><li><strong>Flatten radius</strong> (<code>:473</code>): vertices near a node vertex inherit its rim Z (ponding-basin flattening).</li><li><strong>Terrain Z</strong> (<code>:502</code>): remaining vertices get <code>opts.sampleZ(x,y)</code>.</li></ol><p><code>_addPt</code> (<code>:157</code>) is a spatial-hash snap-merge inserter; <code>interiorPoint</code> (<code>:33</code>) picks hole/region seeds.</p><h2 id="triangulation-terrain-—-mesh2dtriangle-js-mesh2dterrain-js" tabindex="-1">Triangulation &amp; terrain — <code>mesh2dTriangle.js</code> / <code>mesh2dTerrain.js</code> <a class="header-anchor" href="#triangulation-terrain-—-mesh2dtriangle-js-mesh2dterrain-js" aria-label="Permalink to &quot;Triangulation &amp; terrain — `mesh2dTriangle.js` / `mesh2dTerrain.js`&quot;">​</a></h2><ul><li><code>Mesh2DTriangle.triangulate(pslg, quality, ctx)</code> (<code>:92</code>) packs the PSLG into Float64/Int32 arrays and runs Triangle with switches: <code>pQAY</code> (PSLG, quiet, attributes, no-boundary-Steiner when requested), <code>q{minAngle}</code> (default <strong>33°</strong>), <code>a{maxArea}</code> (default 200 m²) or regional area list, <code>S{maxSteiner}</code>. Output vertices are matched back by 1 mm <code>CoordHash</code> (<code>:21</code>); Manning&#39;s n comes from region attribute → subcatchment lookup (<code>manningForSub</code>, <code>:36</code> — priority: land-cover class → <code>nPerv</code> → <code>nImperv</code> → default).</li><li><code>runGeneration(sources, quality, ctx, log)</code> (<code>:251</code>) orchestrates with hard budgets: <ul><li><strong><code>trianglePointBudget</code> = 8000 points</strong> (Triangle WASM heap is fixed at 16 MB) — big models drop subcatchment rings + conduit constraints and reassign roughness by centroid.</li><li><strong><code>autoAreaCap</code></strong> (<code>:331</code>): max area capped to <code>domainArea/15000</code>, minAngle clamped to 30°, <code>maxSteiner</code> 30000, boundary Steiner disabled.</li><li><strong><code>maxTriangleRegions</code> = 256</strong> (<code>:361</code>): beyond that all region seeds collapse and tags/n are assigned by centroid.</li><li><strong>Fallback</strong> to the poly2tri generator (<code>:380</code>) on Triangle failure.</li></ul></li><li><code>Mesh2DTerrain.makeSampler(settings, map)</code> (<code>mesh2dTerrain.js:24</code>): <code>MAPBOX</code> → <code>map.queryTerrainElevation</code>; <code>OPENTOPOGRAPHY_*</code> → OpenTopography bbox API; <code>GEOTIFF</code> → geotiff.js <code>readRasters</code> with <strong>bilinear interpolation</strong> (<code>:109</code>), nodata handling, proj4 reprojection, and <code>refreshBounds()</code> exposing the raster footprint as an auto domain.</li><li><code>resolveVertexElevations(...)</code> (<code>:123</code>): rim-Z first → sampler → <strong>IDW fallback (k=4)</strong> → 0.</li><li><code>thinTerrain(sampler, domain, opts, transform)</code> (<code>:152</code>): <strong>terrain-adaptive thinning</strong> — grid of ≤300×300 candidates scored &quot;most-curved-first&quot; by local surface-normal deviation, accepted with min spacing and edge buffer.</li></ul><h2 id="coupling-inp-serialization" tabindex="-1">Coupling &amp; INP serialization <a class="header-anchor" href="#coupling-inp-serialization" aria-label="Permalink to &quot;Coupling &amp; INP serialization&quot;">​</a></h2><ul><li><code>Mesh2DCoupling.buildVertexNodeMap(indexed, nodes, opts)</code> (<code>mesh2dCoupling.js:5</code>) dedupes vertex↔node rows; default coupling coefficient <code>cd = 0.65</code>.</li><li><code>Mesh2DInp.buildInput(baseInp, cells, map, options)</code> (<code>mesh2dInp.js:162</code>) rejects US units (<code>:163</code>), prefers the indexed mesh (overlaying current dialog solver options onto stored ones, <code>:175-184</code>), and delegates to <code>Mesh2DExport.buildInline</code> (<code>mesh2dExport.js:54</code>) or <code>buildExternal</code> (<code>:68</code>, <code>[2D_MESH_FILE]</code> + <code>.2dm</code>).</li><li>Sections emitted: <code>;; UNITS: SI (m)</code>, <code>;; 2D_ORIGIN lng lat</code>, <code>[2D_OPTIONS]</code>, <code>[2D_VERTICES]</code> (<code>X Y Z TAG</code>), <code>[2D_TRIANGLES]</code> (<code>V1 V2 V3 MANNINGS_N TAG</code>), optional <code>[2D_VERTEX_NODE_MAP]</code>.</li><li><code>Mesh2DExport.optionLines</code> (<code>:22</code>) emits solver options: <code>MAX_TIMESTEP</code>, <code>DRY_DEPTH</code>, <code>COUPLING_CD</code>, <code>COUPLING_SYNC</code>, <code>THETA</code>, <code>CFL_NUMBER</code>, <code>H_MOVE</code>, <code>LTS_TIERS</code>, <code>FROUDE_MAX</code>, <code>LIMITER_EPSILON</code>, <code>FLUX_DH_EPS</code>, <code>CELL_CLOSURE</code>, <code>FACE_RECONSTRUCTION</code>, <code>VFR_MIN_WET_FRAC</code>, <code>INTEGRATOR EXPLICIT</code>, <code>COUPLING_AREA</code>, optional <code>RAINFALL_MODE</code>, <code>REPORT_2D</code>.</li><li>The mesh dialog (<code>mesh2dDialog.js</code>) orchestrates everything from a 3-tab modal (Sources/Quality/Hydraulics): <code>generate()</code> (<code>:369</code>) assembles sources, transform, terrain sampler, quality/ctx, runs <code>Mesh2DTriangle.runGeneration</code>, resolves elevations, builds <code>vertexNodeMap</code>, and calls <code>Net.setIndexedMesh</code>. Defaults (<code>defaultSettings</code>, <code>:16</code>) persist to <code>localStorage</code> with migrations (v4 aligns <code>LTS_TIERS 4</code>, <code>MAX_TIMESTEP 10</code>, <code>H_MOVE 0.003</code>; v5 aligns <code>THETA 0.8</code>, <code>CFL_NUMBER 0.7</code>, <code>FROUDE_MAX 1.5</code>, <code>COUPLING_SYNC 0</code>, <code>FLUX_DH_EPS 0.004</code>, <code>VFR_MIN_WET_FRAC 0.01</code> — all per the engine&#39;s <code>SolverOptions2D.hpp</code> / Ref Manual Vol II Ch9 §9.11).</li></ul><h2 id="rendering-the-2d-simulation" tabindex="-1">Rendering the 2D simulation <a class="header-anchor" href="#rendering-the-2d-simulation" aria-label="Permalink to &quot;Rendering the 2D simulation&quot;">​</a></h2><p>Two complementary layers:</p><ul><li><strong>GeoJSON overlays — <code>mesh2dRender.js</code>:</strong> <code>Mesh2DLayers.ensure(map)</code> (<code>:95</code>) creates sources/layers for vertex points, depth isolines (<code>isolines</code>, <code>:32</code>), depth contour <strong>bands</strong> (<code>contourBands</code>, <code>:50</code> — dry part clipped below the canonical <code>View2D.DEPTH_MASK_M</code> (5 mm) so the uniform-rain film stays invisible), velocity arrows (<code>velocityArrows</code>, <code>:89</code>, threshold <code>mag &lt; 0.002</code>, arrow size <code>√(mag/max)</code> clamped 0.4–1.8), and elevation bands/isolines. <code>onStep(step, frame)</code> (<code>:127</code>) rebuilds the vertex depth field (from <code>frame.vertex.depth</code> or, when the engine emits per-cell depths, area-weighted from <strong>wet cells only</strong> so wet depths never bleed into dry vertices) each animation frame. Exposed in the layer tree (12 toggles).</li><li><strong>WebGL2 Gouraud layer — <code>meshGlLayer.js</code>:</strong> <code>MeshShadeLayer</code> (<code>:6</code>) is a Mapbox custom layer (<code>renderingMode:&#39;2d&#39;</code>) with GLSL ES 3.0 shaders and a 5-stop color ramp (<code>#2e7dd1 → #26a69a → #ffca28 → #f57c00 → #d32f2f</code>). <code>setField</code> (<code>:16</code>) encodes <code>t = clamp((v−min)/(max−min))</code> with wet-only alpha. <code>Mesh2DGL.ensure</code> (<code>:18</code>) adds <code>m2d-smooth-depth-fill</code> and <code>m2d-mesh-terrain</code> below the classic per-cell fill (<code>swmm-2d-mesh-fill</code>, which is colored per-triangle via feature-state <code>resultColor</code>, <code>results.js:393/433</code>).</li></ul><h2 id="the-webgpu-marcher-—-public-webgpu" tabindex="-1">The WebGPU marcher — <code>public/webgpu/</code> <a class="header-anchor" href="#the-webgpu-marcher-—-public-webgpu" aria-label="Permalink to &quot;The WebGPU marcher — `public/webgpu/`&quot;">​</a></h2><ul><li><strong><code>webgpuMarscher.js</code></strong> — <code>buildEdges(mesh)</code> (<code>:23</code>) is a <strong>bit-exact port of the engine&#39;s <code>InertialEdges.cpp</code></strong> (per-triangle centroid/area/bed, edge keys by sorted vertex pair, outward normals, Phase-1 interior edges, <code>cell_lchar = 2·area/xiMax</code>, per-cell CSR). <code>WebGPUMarcher</code> (<code>:171</code>) uploads packed SoA buffers and compiles <strong>one compute pipeline with a 16-binding bind group</strong> (<code>_compile</code>, <code>:338</code>) plus 15 compute pipelines. <code>advance(t0,t1,rain)</code> (<code>:592</code>) mirrors <code>ExplicitInertialSolver::advance</code> — rebuild cadence 4, <code>K=1</code> global-dt path, <code>K&gt;1</code> LTS macro-cycle, <code>dtFloor</code> guards f32 Perot-speed CFL collapse.</li><li><strong><code>shaders/marcher.wgsl</code></strong> (the only shader file) — a 1:1 f64→f32 port of <code>InertialKernels.hpp</code>. Params travel as a flat <code>array&lt;f32&gt;</code> (struct-typed storage bindings misbehave on some drivers). Kernels: <code>faceFlux</code> (de Almeida &amp; Bates local-inertial face update + exporter-cell positivity budget <code>β/3·V</code>), <code>cellUpdate</code> (Perot cell discharge), <code>lazySources</code>, <code>seedActive</code> (hysteretic activation <code>h_on = hMove+0.001</code>, <code>h_off = hMove−0.001</code>; coupling cells pinned), <code>halo</code>, <code>couplingExchange</code> (C¹-regularized orifice <code>Q = cd·Aeff·√(2g)·φ</code>, drain capped by <code>β·V/dt</code>, spill capped by a per-node drawn ledger), <code>cflReduce</code>/<code>cflArgmin</code> (atomicMin dt0 bitcast + argmin cell), and the LTS v2 set (<code>settleAcc</code>, <code>tierAssign</code>, <code>faceTierAssign</code>, <code>degenTier</code>/<code>degenFaceTier</code>, <code>faceFluxLts</code>, <code>cellUpdateLts</code> with refire = <code>2^(tier_exp − face_tier)</code>).</li><li><strong><code>couplingSplit.js</code></strong> — the M2 split machinery (worker-safe): <code>parse2DMesh</code>/<code>parse2DOptions</code> (<code>:18</code>/<code>:43</code>), <code>nodeOrder</code> (<code>:67</code>, node index = parse order across JUNCTIONS/OUTFALLS/STORAGE/DIVIDERS sorted by global text position — a fixed walk mis-indexes some INPs), <code>buildVertexStencil</code> (<code>:95</code>, Jawahar-Kamath partition-of-unity weights), <code>parseCoupling</code> (<code>:144</code>, crown = <code>(invert+fullDepth)·len12</code>; <code>COUPLING_AREA DEFAULT</code> → <code>A = clamp(1.25·Amax_conduit, 0.05, 2.0)</code> m²; <strong>vertex points resolve to the lowest-bed incident cell</strong>, per <code>SurfaceRouter2D.cpp:394-412</code>), <code>build1DInp</code> (<code>:283</code>, strips 2D sections, forces <code>ALLOW_PONDING YES</code>, <strong>preserves the model&#39;s own adaptive VARIABLE_STEP</strong> — a former pin to 0 corrupted the 1D solve), <code>rainMpsAt</code> (<code>:331</code>, gage-mean rain, INTENSITY/CUMULATIVE/VOLUME handling), and the core <strong><code>runSplit</code></strong> (<code>:400</code>): fill each coupling window by time, freeze 1D node state into 9-float <code>cplF</code> rows, guard non-finite state (<code>COUPLING_STATE_NONFINITE</code>), <code>marcher.advance</code>, feed <code>∫Q</code> back via <code>setLatInflow(exch/dtBatch)</code> (matching the engine&#39;s two-window-mean queue delivery), emit frames, compute real mass balance.</li><li><strong><code>gpu2dWorker.js</code></strong> — the production worker (same <code>run2d</code> contract as <code>openSwmm2dWorker.js</code>): loads the WASM engine for the <strong>1D leg only</strong>, requires <code>maxStorageBuffersPerShaderStage: 16</code> (<code>requestGpuDevice</code>, <code>:70</code>; throws <code>WEBGPU_UNAVAILABLE</code> otherwise), writes a 1D-only INP, <code>setPondArea(tri_area)</code> per coupling node, then <code>CouplingSplit.runSplit</code> with a 60 s coupling window.</li><li><strong><code>harness.html</code></strong> — M0/M1/M2 validation page. Gates: <strong>conservation ≤ 0.5 %, mean-depth ≤ 1e-3 m, median Pearson correlation ≥ 0.5</strong>; M2 exchange within 5 %, temporal corr ≥ 0.9.</li></ul><h2 id="webgpu-roadmap-status-from-webgpu-plan-md" tabindex="-1">WebGPU roadmap status (from <code>WEBGPU_PLAN.md</code>) <a class="header-anchor" href="#webgpu-roadmap-status-from-webgpu-plan-md" aria-label="Permalink to &quot;WebGPU roadmap status (from `WEBGPU_PLAN.md`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Milestone</th><th>Scope</th><th>Status</th></tr></thead><tbody><tr><td>M0</td><td>Harness: <code>navigator.gpu</code> detect, device, canvas</td><td>✅ (Chrome headed only; headless has no WebGPU)</td></tr><tr><td>M1</td><td>Global-dt marcher: faceFlux+cellUpdate+rain</td><td>✅ statistical parity</td></tr><tr><td>M2</td><td>1D+2D split coupling</td><td>✅ PASS (marcher-cpl: exch Δ≈0, medianCorr 0.865, temporalCorr 1.0)</td></tr><tr><td>M2.x</td><td>Vertex coupling + production worker</td><td>✅ Bellinge runs on GPU</td></tr><tr><td>M3</td><td>Boundary conditions + LTS v2</td><td>✅ LTS v2 done; NORMAL_FLOW / SPECIFIED_STAGE pending</td></tr><tr><td>M4</td><td>renderDepths + UI WebGPU/WASM toggle</td><td>pending</td></tr><tr><td>M5</td><td>Benchmark &amp; hosting</td><td>pending</td></tr></tbody></table><p><strong>Hard limits &amp; honest verdicts recorded in the plan:</strong></p><ul><li><strong>Apple Silicon / Metal (≤10 storage buffers) cannot run the backend</strong> — 16 storage buffers exceed Metal&#39;s limit; the worker throws <code>WEBGPU_UNAVAILABLE</code> and the app falls back to WASM.</li><li>f32/f64 divergence in <code>max|Δdepth|</code> is accepted; validation is statistical.</li><li><strong>Honest performance verdict:</strong> GPU 2D is fast (0.13 ms/substep) but the 1D dynamic wave is ~90 % of wall time in both backends, so the split is currently <em>on par with</em> the engine, not faster.</li></ul>',26)])])}const m=o(a,[["render",s]]);export{g as __pageData,m as default};
